ALTER TABLE public.items ADD COLUMN IF NOT EXISTS latitude double precision, ADD COLUMN IF NOT EXISTS longitude double precision;
ALTER TABLE public.items DROP CONSTRAINT IF EXISTS items_condition_check;
ALTER TABLE public.items ADD CONSTRAINT items_condition_check CHECK (condition IN ('new','good','used','like_new','needs_repair'));
ALTER TABLE public.items ADD CONSTRAINT items_coordinates_check CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180));
CREATE TABLE public.item_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.items(id) ON DELETE CASCADE, storage_path text NOT NULL, sort_order integer NOT NULL CHECK (sort_order BETWEEN 0 AND 4), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(item_id,sort_order));
GRANT SELECT ON public.item_photos TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.item_photos TO authenticated;
GRANT ALL ON public.item_photos TO service_role;
ALTER TABLE public.item_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Photos are public" ON public.item_photos FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Owners manage photos" ON public.item_photos FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id AND i.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id AND i.user_id=auth.uid()) AND split_part(storage_path,'/',1)=auth.uid()::text);
INSERT INTO public.item_photos(item_id,storage_path,sort_order) SELECT id,photo_url,0 FROM public.items WHERE photo_url IS NOT NULL;
CREATE TYPE public.request_status AS ENUM ('pending','accepted','declined','completed');
CREATE TABLE public.requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),item_id uuid NOT NULL REFERENCES public.items(id) ON DELETE CASCADE,requester_id uuid NOT NULL,owner_id uuid NOT NULL,message text NOT NULL DEFAULT '' CHECK(char_length(message)<=500),status public.request_status NOT NULL DEFAULT 'pending',requester_name text NOT NULL DEFAULT '' CHECK(char_length(requester_name)<=80),requester_phone text NOT NULL DEFAULT '' CHECK(requester_phone='' OR requester_phone ~ '^\+?[0-9 ()-]{7,20}$'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(item_id,requester_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.requests TO authenticated;
GRANT ALL ON public.requests TO service_role;
ALTER TABLE public.requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants view requests" ON public.requests FOR SELECT TO authenticated USING(requester_id=auth.uid() OR owner_id=auth.uid());
CREATE POLICY "Requesters create valid requests" ON public.requests FOR INSERT TO authenticated WITH CHECK(requester_id=auth.uid() AND requester_id<>owner_id AND status='pending' AND EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id AND i.user_id=owner_id AND i.is_available));
CREATE POLICY "Owners update requests" ON public.requests FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY "Requesters cancel pending requests" ON public.requests FOR DELETE TO authenticated USING(requester_id=auth.uid() AND status='pending');
INSERT INTO public.requests(id,item_id,requester_id,owner_id,message,status,requester_name,requester_phone,created_at) SELECT r.id,r.item_id,r.requester_id,i.user_id,r.message,r.status::public.request_status,r.requester_name,r.requester_phone,r.created_at FROM public.item_requests r JOIN public.items i ON i.id=r.item_id WHERE r.requester_id<>i.user_id;
COMMENT ON TABLE public.item_requests IS 'DEPRECATED: replaced by public.requests; original contact data preserved and backfilled.';
CREATE FUNCTION public.validate_request_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id IS DISTINCT FROM OLD.id OR NEW.item_id IS DISTINCT FROM OLD.item_id OR NEW.requester_id IS DISTINCT FROM OLD.requester_id OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.message IS DISTINCT FROM OLD.message OR NEW.requester_name IS DISTINCT FROM OLD.requester_name OR NEW.requester_phone IS DISTINCT FROM OLD.requester_phone OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Request details cannot be changed'; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='pending' AND NEW.status IN ('accepted','declined')) OR (OLD.status='accepted' AND NEW.status IN ('completed','declined'))) THEN RAISE EXCEPTION 'Invalid request status transition'; END IF; IF NEW.status IN ('accepted','completed') AND NEW.status IS DISTINCT FROM OLD.status THEN PERFORM 1 FROM public.items WHERE id=NEW.item_id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=NEW.item_id AND is_available) THEN RAISE EXCEPTION 'This item is no longer available'; END IF; IF EXISTS(SELECT 1 FROM public.requests WHERE item_id=NEW.item_id AND id<>NEW.id AND status IN ('accepted','completed')) THEN RAISE EXCEPTION 'Another request is already accepted'; END IF; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER requests_validate BEFORE UPDATE ON public.requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_update();
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES public.requests(id) ON DELETE CASCADE,sender_id uuid NOT NULL,body text NOT NULL CHECK(char_length(btrim(body)) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.messages TO authenticated;
GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read messages" ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.requests r WHERE r.id=request_id AND (r.owner_id=auth.uid() OR r.requester_id=auth.uid())));
CREATE POLICY "Participants send messages" ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.requests r WHERE r.id=request_id AND (r.owner_id=auth.uid() OR r.requester_id=auth.uid())));
CREATE INDEX requests_owner_idx ON public.requests(owner_id,status);
CREATE INDEX requests_requester_idx ON public.requests(requester_id,status);
CREATE INDEX messages_request_idx ON public.messages(request_id,created_at);
CREATE INDEX IF NOT EXISTS items_category_idx ON public.items(category);
CREATE INDEX IF NOT EXISTS items_created_idx ON public.items(created_at DESC);
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages;